import { MakeLogicType, afterMount, kea, path } from 'kea'

import { toolStreamEventsLogic } from 'products/posthog_ai/frontend/api/logics'

import { biWorksheetsLogic } from './biWorksheetsLogic'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export type biAgentSyncLogicType = MakeLogicType<{}, {}>

export const biAgentSyncLogic = kea<biAgentSyncLogicType>([
    path(['products', 'business_intelligence', 'biAgentSyncLogic']),
    afterMount(({ cache }) => {
        cache.disposables.add(
            () => {
                toolStreamEventsLogic.actions.registerToolListener('bi-worksheets', {
                    tools: ['insight-create', 'insight-update'],
                    foregroundOnly: true,
                    onEvent: (event) => {
                        if (event.phase === 'completed') {
                            biWorksheetsLogic.findMounted()?.actions.loadWorksheets()
                        }
                    },
                })
                return () => toolStreamEventsLogic.actions.deregisterToolListener('bi-worksheets')
            },
            'tools',
            { pauseOnPageHidden: false }
        )
    }),
])
